package shadcnscalajs.blocks.dashboard01

import com.raquo.laminar.api.L.*
import shadcnscalajs.ui.*

/** Port of shadcn-svelte `blocks/dashboard-01/components/app-sidebar.svelte` — the inset sidebar shell for the
  * dashboard: brand header, primary nav, documents list, secondary nav pinned to the bottom, and the account menu.
  *
  * Upstream's `data.navClouds` is defined but never passed to any child component (dead data in the source file
  * itself), so it is not ported here either.
  */
object AppSidebar:

  final case class NavItem(title: String, url: String, icon: () => SvgElement)
  final case class DocItem(name: String, url: String, icon: () => SvgElement)
  final case class UserInfo(name: String, email: String, initials: String)

  // Upstream icons with no equivalent concept registered across all five `Icons` libraries are substituted with the
  // closest available concept (documented in task-6-report.md) rather than hand-adding new per-library SVG path data,
  // which is out of this task's scope (see Task 1, which added exactly one new concept, `gallery-vertical-end`).
  private val user: UserInfo = UserInfo("shadcn", "m@example.com", "CN")

  private val navMain: List[NavItem] = List(
    NavItem("Dashboard", "#", () => Icons.layoutDashboard()),
    NavItem("Lifecycle", "#", () => Icons.fileText()),
    NavItem("Analytics", "#", () => Icons.activity()),
    NavItem("Projects", "#", () => Icons.folder()),
    NavItem("Team", "#", () => Icons.user())
  )

  private val navSecondary: List[NavItem] = List(
    NavItem("Settings", "#", () => Icons.settings2()),
    NavItem("Get Help", "#", () => Icons.circleHelp()),
    NavItem("Search", "#", () => Icons.search())
  )

  private val documents: List[DocItem] = List(
    DocItem("Data Library", "#", () => Icons.cloud()),
    DocItem("Reports", "#", () => Icons.fileBarChart()),
    DocItem("Word Assistant", "#", () => Icons.bookOpen())
  )

  private def brandItem: HtmlElement =
    li(
      dataAttr("slot") := "sidebar-menu-item",
      dataAttr("sidebar") := "menu-item",
      cls := "group/menu-item relative",
      // Upstream spreads the menu-button props onto an `<a>` via a child snippet; `menuButtonLink` reproduces that
      // without nesting an anchor inside `menuButton`'s `<button>`.
      Sidebar.menuButtonLink()(
        cls := "data-[slot=sidebar-menu-button]:!p-1.5",
        href := "#",
        Icons.command(svg.cls := "!size-5"),
        span(cls := "text-base font-semibold", "Acme Inc.")
      )
    )

  def apply(openVar: Var[Boolean])(mods: Modifier[HtmlElement]*): HtmlElement =
    Sidebar.root(variant = Sidebar.Variant.Inset, collapsible = Sidebar.Collapsible.Icon, openVar = openVar)(
      mods,
      Sidebar.header(Sidebar.menu(brandItem)),
      Sidebar.content(
        NavMain(navMain),
        NavDocuments(documents),
        NavSecondary(navSecondary, cls := "mt-auto")
      ),
      Sidebar.footer(NavUser(user))
    )

package shadcnscalajs.blocks.dashboard01

import com.raquo.laminar.api.L.*
import shadcnscalajs.ui.*
import shadcnscalajs.blocks.dashboard01.AppSidebar.NavItem

/** Port of shadcn-svelte `blocks/dashboard-01/components/nav-secondary.svelte` — a small nav group pinned to the bottom
  * of the sidebar content via the caller's `mt-auto`.
  */
object NavSecondary:

  def apply(items: List[NavItem], mods: Modifier[HtmlElement]*): HtmlElement =
    Sidebar.group(
      mods,
      Sidebar.groupContent(
        Sidebar.menu(
          items.map { item =>
            // `menuButtonLink` renders the anchor itself; nesting it inside `menuItem`'s built-in `menuButton` would
            // put an `<a>` inside a `<button>`, so the `li` is hand-built instead.
            li(
              dataAttr("slot") := "sidebar-menu-item",
              dataAttr("sidebar") := "menu-item",
              cls := "group/menu-item relative",
              Sidebar.menuButtonLink()(href := item.url, item.icon(), span(item.title))
            )
          }
        )
      )
    )

package shadcnscalajs.blocks.dashboard01

import com.raquo.laminar.api.L.*
import shadcnscalajs.ui.*
import shadcnscalajs.blocks.dashboard01.AppSidebar.DocItem

/** Port of shadcn-svelte `blocks/dashboard-01/components/nav-documents.svelte` — a document list hidden once the
  * sidebar collapses to icons, each row with a hover-revealed action menu.
  *
  * Upstream flips the action menu's `side`/`align` on `sidebar.useSidebar().isMobile`; that per-instance mobile query
  * is not exposed by `shadcnscalajs.ui.Sidebar`, so — matching `sidebar07.NavProjects`'s precedent — the menu just uses
  * `DropdownMenu`'s default placement.
  */
object NavDocuments:

  // Position/reveal-on-hover classes live on this *wrapper*, not the button: `DropdownMenu`'s root is
  // `position: relative`, which would otherwise become the nearest positioned ancestor and pin the action into the
  // row's inline flow instead of floating it to the top-right corner. Same structure as `sidebar07.NavProjects`.
  private val actionWrapperClass =
    "absolute top-1.5 right-1 peer-data-[size=default]/menu-button:top-2 peer-data-[size=lg]/menu-button:top-2.5 peer-data-[size=sm]/menu-button:top-1 group-data-[collapsible=icon]:hidden group-focus-within/menu-item:opacity-100 group-hover/menu-item:opacity-100 peer-data-active/menu-button:text-sidebar-accent-foreground md:opacity-0 data-open:opacity-100"

  private val actionTriggerClass =
    "flex aspect-square w-5 items-center justify-center rounded-md p-0 text-sidebar-foreground outline-hidden ring-sidebar-ring transition-transform after:absolute after:-inset-2 md:after:hidden hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-2 [&>svg]:size-4 [&>svg]:shrink-0"

  private def documentItem(item: DocItem): HtmlElement =
    li(
      dataAttr("slot") := "sidebar-menu-item",
      dataAttr("sidebar") := "menu-item",
      cls := "group/menu-item relative",
      Sidebar.menuButtonLink()(href := item.url, item.icon(), span(item.name)),
      div(
        cls := actionWrapperClass,
        DropdownMenu.itemsWithTrigger(
          Seq(
            dataAttr("slot") := "sidebar-menu-action",
            dataAttr("sidebar") := "menu-action",
            cls := actionTriggerClass
          )
        )(
          Icons.moreHorizontal(),
          span(cls := "sr-only", "More")
        ) { ctx =>
          Seq(
            ctx.item(Icons.folder(svg.cls := "text-muted-foreground"), span("Open")),
            ctx.item(Icons.forward(svg.cls := "text-muted-foreground"), span("Share")),
            ctx.separator(),
            ctx.item(Menu.destructive, Icons.trash2(svg.cls := "text-muted-foreground"), span("Delete"))
          )
        }
      )
    )

  def apply(items: List[DocItem]): HtmlElement =
    Sidebar.group(
      cls := "group-data-[collapsible=icon]:hidden",
      Sidebar.groupLabel("Documents"),
      Sidebar.menu(
        items.map(documentItem),
        Sidebar.menuItem(
          cls := "text-sidebar-foreground/70",
          Icons.moreHorizontal(svg.cls := "text-sidebar-foreground/70"),
          span("More")
        )
      )
    )

package shadcnscalajs.blocks.dashboard01

import com.raquo.laminar.api.L.*
import shadcnscalajs.ui.*

/** Port of shadcn-svelte `blocks/dashboard-01/components/section-cards.svelte` — the four KPI cards at the top of the
  * dashboard.
  */
object SectionCards:

  private final case class Metric(
      description: String,
      amount: String,
      trendUp: Boolean,
      badgeText: String,
      footerHeadline: String,
      footerDetail: String
  )

  private val metrics: List[Metric] = List(
    Metric(
      "Total Revenue",
      "$1,250.00",
      trendUp = true,
      "+12.5%",
      "Trending up this month",
      "Visitors for the last 6 months"
    ),
    Metric("New Customers", "1,234", trendUp = false, "-20%", "Down 20% this period", "Acquisition needs attention"),
    Metric("Active Accounts", "45,678", trendUp = true, "+12.5%", "Strong user retention", "Engagement exceed targets"),
    Metric("Growth Rate", "4.5%", trendUp = true, "+4.5%", "Steady performance increase", "Meets growth projections")
  )

  // Upstream's `TrendingDownIcon` has no equivalent concept registered across all five `Icons` libraries; a
  // rotated `trendingUp` is visually indistinguishable from a dedicated down-trend glyph.
  private def trendIcon(trendUp: Boolean, mods: Modifier[SvgElement]*): SvgElement =
    if trendUp then Icons.trendingUp(mods*) else Icons.trendingUp(svg.cls := "rotate-180", mods)

  private def metricCard(metric: Metric): HtmlElement =
    Card(
      cls := "@container/card",
      Card.header(
        Card.description(metric.description),
        Card.title(cls := "text-2xl font-semibold tabular-nums @[250px]/card:text-3xl", metric.amount),
        Card.action(
          Badge.of(
            _.variant(Badge.Variant.Outline),
            _ => trendIcon(metric.trendUp),
            _ => metric.badgeText
          )
        )
      ),
      Card.footer(
        cls := "flex-col items-start gap-1.5 text-sm",
        div(
          cls := "line-clamp-1 flex gap-2 font-medium",
          metric.footerHeadline,
          trendIcon(metric.trendUp, svg.cls := "size-4")
        ),
        div(cls := "text-muted-foreground", metric.footerDetail)
      )
    )

  def apply(): HtmlElement =
    div(
      cls := "grid grid-cols-1 gap-4 px-4 *:data-[slot=card]:bg-gradient-to-t *:data-[slot=card]:from-primary/5 *:data-[slot=card]:to-card *:data-[slot=card]:shadow-xs lg:px-6 @xl/main:grid-cols-2 @5xl/main:grid-cols-4 dark:*:data-[slot=card]:bg-card",
      metrics.map(metricCard)
    )
